css:
.refund-v2{--pbg:#0c0d0e;--pgold:#d9b363;--ppaper:#f5efe5;--pmuted:#c7c1b7;background:var(--pbg);color:var(--ppaper);font:16px/1.75 system-ui,-apple-system,"Segoe UI",sans-serif;overflow-wrap:break-word}
.refund-v2 *, .refund-v2 *:before,.refund-v2 *:after{box-sizing:border-box}
.refund-v2 a{color:#ebc87f;text-underline-offset:4px}
.refund-v2 a:focus-visible,.refund-v2 summary:focus-visible{outline:3px solid #eac77d;outline-offset:3px}
.refund-v2 .refund-hero-shell{background:radial-gradient(ellipse at 76% 4%,#4d3b1d30,transparent 45%),linear-gradient(#111214,#0c0d0e);border-bottom:1px solid #41372b}
.refund-v2 .refund-hero-inner,.refund-v2 .refund-layout{width:min(1210px,calc(100% - 44px));margin:0 auto}
.refund-v2 .refund-hero-inner{padding:28px 0 50px}
.refund-v2 .customer-breadcrumb{margin:0;padding:0;font-size:12px;min-height:0;color:#bcb6ad}
.refund-v2 .customer-breadcrumb ol{margin:0;padding:0;display:flex;flex-wrap:wrap;list-style:none;gap:10px}
.refund-v2 .customer-breadcrumb li+li:before{content:'/';padding-right:10px;color:#8d8578}
.refund-v2 .refund-hero-intro{border:0;background:none;padding:0;margin:45px 0 0;max-width:780px}
.refund-v2 .refund-hero-intro .home-eyebrow{color:var(--pgold);font:750 11px/1.5 system-ui,sans-serif;letter-spacing:.16em;text-transform:uppercase;margin:0 0 14px}
.refund-v2 .refund-hero-intro h1{color:var(--ppaper);font:500 clamp(43px,5vw,72px)/1.1 Georgia,"Times New Roman",serif;letter-spacing:-.035em;margin:0 0 19px}
.refund-v2 .refund-hero-intro>p:last-child{color:var(--pmuted);font-size:17px;line-height:1.8;margin:0;max-width:675px}
.refund-v2 .refund-updated{display:inline-block;margin:20px 0 0;color:#ceb57e;font-size:12px}
.refund-v2 .refund-layout{display:grid;grid-template-columns:245px minmax(0,1fr);align-items:start;gap:38px;padding:46px 0 75px}
.refund-v2 .refund-sidebar{position:sticky;top:90px}
.refund-v2 .refund-toc{border:1px solid #41372b;border-radius:12px;background:#151617;padding:21px 14px}
.refund-v2 .refund-toc-title{font:750 11px/1.5 system-ui,sans-serif;letter-spacing:.15em;color:var(--pgold);text-transform:uppercase;margin:0 10px 15px}
.refund-v2 .refund-toc a,.refund-v2 .refund-mobile-toc a{display:flex;align-items:flex-start;gap:10px;padding:10px 11px;color:#d5cfc5;text-decoration:none;border-radius:6px;font-size:12px;line-height:1.5}
.refund-v2 .refund-toc a:hover,.refund-v2 .refund-mobile-toc a:hover{color:#f7dfa7;background:#27231c}
.refund-v2 .refund-toc a span,.refund-v2 .refund-mobile-toc a span{color:var(--pgold);font-size:11px;font-weight:700;flex-shrink:0}
.refund-v2 .refund-sidebar-note{padding:19px 12px;color:#c9c0b1;font-size:12px;line-height:1.65}
.refund-v2 .refund-sidebar-note a{display:block;font-weight:650;margin-top:7px}
.refund-v2 .refund-mobile-toc{display:none}
.refund-v2 .refund-content{min-width:0;counter-reset:refund-section}
.refund-v2 .refund-summary{background:linear-gradient(120deg,#202020,#131517);border:1px solid #8a703f;border-radius:14px;padding:31px;margin-bottom:25px}
.refund-v2 .refund-kicker{color:var(--pgold);text-transform:uppercase;font-size:11px;letter-spacing:.16em;font-weight:700;margin:0 0 12px}
.refund-v2 .refund-summary h2{font:500 clamp(26px,3vw,35px)/1.25 Georgia,serif;color:var(--ppaper);margin:0 0 22px}
.refund-v2 .refund-summary-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}
.refund-v2 .refund-summary-item{border:1px solid #514736;border-radius:9px;background:#141414;padding:16px 13px}
.refund-v2 .refund-summary-item strong{display:block;color:#e7c179;font-size:13px;margin:0 0 8px;font-weight:700}
.refund-v2 .refund-summary-item p{color:#d4cfc7;font-size:12px;line-height:1.65;margin:0}
.refund-v2 .refund-card{counter-increment:refund-section;margin:0 0 17px;padding:31px 34px;background:#141517;border:1px solid #3b362f;border-radius:12px;scroll-margin-top:94px}
.refund-v2 .refund-card h2{font:500 clamp(25px,3vw,34px)/1.25 Georgia,serif;color:var(--ppaper);letter-spacing:-.018em;display:flex;align-items:baseline;gap:15px;margin:0 0 18px}
.refund-v2 .refund-card h2:before{content:counter(refund-section,decimal-leading-zero);font:700 12px/1.6 system-ui,sans-serif;letter-spacing:.08em;color:var(--pgold)}
.refund-v2 .refund-card p{font:400 14px/1.9 system-ui,-apple-system,"Segoe UI",sans-serif;color:#d2cbc0;margin:0 0 13px;max-width:78ch}
.refund-v2 .refund-card p:last-child{margin-bottom:0}
.refund-v2 .refund-card h3{font:700 15px/1.5 system-ui,sans-serif;color:#ead7af;margin:21px 0 7px}
.refund-v2 .refund-card h3:first-of-type{margin-top:8px}
.refund-v2 .refund-cookie-help{margin-top:18px!important;border-top:1px solid #3e382b;padding-top:14px;font-size:13px!important}
.refund-v2 .legacy-anchor{scroll-margin-top:90px}
.refund-v2 .refund-contact-card{display:flex;justify-content:space-between;gap:24px;align-items:center;padding:29px 32px;border-radius:12px;border:1px solid #9e7d40;background:linear-gradient(115deg,#252016,#191714)}
.refund-v2 .refund-contact-card h2{font:500 29px/1.25 Georgia,serif;color:var(--ppaper);margin:0 0 7px}
.refund-v2 .refund-contact-card p{font-size:13px;color:var(--pmuted);margin:0}
.refund-v2 .refund-contact-card a{flex-shrink:0;border:1px solid #d0aa5c;color:#18130e;background:#e1ba6d;border-radius:7px;padding:11px 18px;font-size:13px;font-weight:700;text-decoration:none;min-height:44px}
@media(max-width:940px){.refund-v2 .refund-layout{grid-template-columns:205px minmax(0,1fr);gap:22px}.refund-v2 .refund-summary-grid{grid-template-columns:1fr}.refund-v2 .refund-summary-item{padding:12px}.refund-v2 .refund-card{padding:26px}}
@media(max-width:740px){.refund-v2 .refund-hero-inner,.refund-v2 .refund-layout{width:calc(100% - 34px)}.refund-v2 .refund-hero-inner{padding:24px 0 35px}.refund-v2 .refund-hero-intro{margin-top:38px}.refund-v2 .refund-hero-intro>p:last-child{font-size:14px}.refund-v2 .refund-layout{display:block;padding:26px 0 60px}.refund-v2 .refund-sidebar{display:none}.refund-v2 .refund-mobile-toc{display:block;border:1px solid #685139;background:#181714;border-radius:12px;overflow:hidden;margin-bottom:21px}.refund-v2 .refund-mobile-toc summary{display:flex;align-items:center;justify-content:space-between;min-height:52px;padding:14px 17px;color:#f0d9a7;font-size:13px;font-weight:700;cursor:pointer;list-style:none}.refund-v2 .refund-mobile-toc summary::-webkit-details-marker{display:none}.refund-v2 .refund-mobile-toc summary:after{content:'⌄';font-size:19px}.refund-v2 .refund-mobile-toc[open] summary:after{content:'⌃'}.refund-v2 .refund-mobile-links{border-top:1px solid #574631;padding:5px}.refund-v2 .refund-summary{padding:23px 20px;margin-bottom:19px}.refund-v2 .refund-card{padding:22px 19px;margin-bottom:14px}.refund-v2 .refund-card h2{font-size:24px;gap:10px}.refund-v2 .refund-card p{font-size:14px;line-height:1.85}.refund-v2 .refund-contact-card{display:block;padding:22px 19px}.refund-v2 .refund-contact-card h2{font-size:25px}.refund-v2 .refund-contact-card a{display:inline-flex;margin-top:19px}}
@media(prefers-reduced-motion:reduce){.refund-v2{scroll-behavior:auto}}

.refund-v2 .refund-hero-actions{display:flex;align-items:center;flex-wrap:wrap;gap:12px;margin:28px 0 0}
.refund-v2 .refund-hero-actions a{display:inline-flex;align-items:center;justify-content:center;text-align:center;min-height:48px;padding:11px 20px;font:700 13px/1.45 system-ui,sans-serif;text-decoration:none;border-radius:7px;border:1px solid #c9a352}
.refund-v2 .refund-hero-actions .refund-primary{color:#1a150e;background:#e2b656}
.refund-v2 .refund-hero-actions .refund-secondary{color:#f2dfb9;background:transparent}
.refund-v2 .refund-hero-actions a:hover{filter:brightness(1.08)}
.refund-v2 .refund-hero-note{margin:12px 0 0;color:#c7baa1;font:400 12px/1.6 system-ui,sans-serif}
.refund-v2 .refund-summary .refund-summary-grid{grid-template-columns:repeat(3,minmax(0,1fr))}
.refund-v2 .refund-summary-item strong{font-size:14px}
.refund-v2 .refund-intro-note{font:400 13px/1.7 system-ui,sans-serif;color:#d3c9b8;margin:17px 0 0}
.refund-v2 .refund-card{max-width:none;scroll-margin-top:110px}
.refund-v2 .refund-card .refund-inline-note{border-left:2px solid #cda655;padding:10px 13px;margin-top:15px;color:#eadab7;background:#29231a;font:500 13px/1.7 system-ui,sans-serif}
.refund-v2 .refund-form-card{background:#141517;border:1px solid #937440;border-radius:12px;padding:30px 32px;max-width:none;scroll-margin-top:105px;margin:25px 0 0}
.refund-v2 .refund-form-kicker{color:#eac77d;font:700 11px/1.5 system-ui,sans-serif;text-transform:uppercase;letter-spacing:.14em;margin-bottom:9px}
.refund-v2 .refund-form-card #request-title{font:500 clamp(27px,3vw,36px)/1.22 Georgia,serif;color:#f5efe5;letter-spacing:-.02em;margin:0 0 14px}
.refund-v2 .refund-form-card #request-guidance{font:400 14px/1.75 system-ui,sans-serif;color:#cfc6b7;margin:0 0 22px;max-width:76ch}
.refund-v2 #customerRequestForm,.refund-v2 #requestReview,.refund-v2 #requestSuccess{max-width:none;width:100%;border-radius:10px;border:1px solid #d2c3a6;box-shadow:none}
.refund-v2 #customerRequestForm{padding:25px 26px}
.refund-v2 #customerRequestForm .request-fields{column-gap:20px;row-gap:16px}
.refund-v2 #customerRequestForm label{font-size:13px;font-weight:600}
.refund-v2 #customerRequestForm input:not([type=hidden]):not([type=checkbox]),.refund-v2 #customerRequestForm textarea{border-radius:6px}
.refund-v2 #customerRequestForm input[type=checkbox]{width:18px;height:18px;accent-color:#9e7225}
.refund-v2 #customerRequestForm .request-check{font-weight:400}
.refund-v2 #customerRequestForm .request-check span{font-size:13px;line-height:1.65}
.refund-v2 #reviewRequest{font-size:14px;min-height:48px;white-space:normal}
.refund-v2 #requestReview,.refund-v2 #requestSuccess{margin-top:14px;padding:25px}
.refund-v2 #requestReview[hidden],.refund-v2 #requestSuccess[hidden]{display:none!important}
.refund-v2 #requestStatus{font-size:13px}
.refund-v2 .refund-policy-help{margin:19px 0 0;padding:16px;border:1px solid #514936;border-radius:8px;background:#191a1a;color:#dfd5c6;font-size:13px;line-height:1.75}
.refund-v2 .refund-policy-help a{font-weight:600}
.refund-v2 .refund-sidebar-note{font-size:12px}
@media(max-width:1100px) and (min-width:741px){.refund-v2 #customerRequestForm .request-fields{grid-template-columns:1fr}}
@media(max-width:940px){.refund-v2 .refund-summary .refund-summary-grid{grid-template-columns:1fr}}
@media(max-width:740px){.refund-v2 .refund-hero-actions{display:grid;grid-template-columns:1fr;gap:10px}.refund-v2 .refund-hero-actions a{width:100%}.refund-v2 .refund-form-card{padding:21px 16px}.refund-v2 #customerRequestForm{padding:21px 15px}.refund-v2 #customerRequestForm .request-fields{grid-template-columns:1fr}.refund-v2 #requestReview,.refund-v2 #requestSuccess{padding:19px 15px}}
